INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('finance-fabi-reform','法币改革','finance','point','day',NULL,NULL,'财政部于1935年11月3日公布改革办法，自11月4日起实施。',1935,11,3,23230,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'国民政府将中央、中国、交通三家银行发行的钞票定为法币，集中钞票发行与兑换管理，并停止以银元和白银作为流通货币。改革改变了中国币制和白银货币流通格局。',NULL,NULL,'[{"label":"中国银行：法币改革史料","url":"https://www.boc.cn/aboutboc/ab7/200809/t20080926_6917.html"}]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('finance-official-jiaozi-issued','官交子发行','finance','point','month',NULL,NULL,'天圣二年（1024）二月官交子正式发行；益州交子务于前一年设立。',1024,2,NULL,12289,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'北宋在益州设交子务，收归民间交子发行权并开始发行官交子。纸币用于缓解四川铁钱沉重、携带不便造成的交易困难，成为国家管理纸币发行的早期制度实践。',NULL,NULL,'[]');
INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('finance-qing-fixed-ding-tax','滋生人丁永不加赋','finance','point','year',NULL,NULL,'康熙五十一年（1712）颁旨；后续各省执行与丁银摊入田亩并非同一时点。',1712,12,NULL,20555,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'清廷以康熙五十年（1711）在册丁额为定额，规定此后新增人丁不再增加丁银。政策冻结人头税总额，为雍正时期将丁银摊入田赋的改革奠定制度背景。',NULL,NULL,'[]');
